package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.documental.*;import cl.nexbyte.siger.institucional.robustez.FalloTecnico;
import java.nio.file.*;import java.util.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class CuarentenaDocumentalTest {
 @TempDir Path temp;CuarentenaFixture f;
 @BeforeEach void setup()throws Exception{f=new CuarentenaFixture(temp);}
 @AfterEach void close()throws Exception{if(f!=null)f.close();}
 void denied(int status,Runnable op){assertEquals(status,assertThrows(FalloTecnico.class,op::run).status);}
 long count(String t){return f.x.d.db.sql.queryForObject("SELECT COUNT(*) FROM "+t,Long.class);}
 CuarentenaDocumental.Incidente aislar(DocumentosRequerimiento.Documento doc){return f.q.aislar(f.x.f.a(f.x.f.ti),f.x.key(),f.solicitud(doc));}
 @Test void aislamientoNoAlteraOriginalReservaNiConcedeLecturaATi()throws Exception{
  var x=f.x;var d=x.cargar();var original=x.d.db.sql.queryForMap("SELECT * FROM institution_document WHERE id=?",d.id().toString());var policy=x.d.db.sql.queryForMap("SELECT * FROM requirement_document_policy WHERE document_id=?",d.id().toString());var ref=x.docs.referencia(x.f.a(x.f.profA),x.req,d.id(),"CONTENIDO");var file=x.docs.verificarArchivo(ref);var h=aislar(d);
  assertEquals("RETENIDO",h.estado());assertFalse(h.verificable());var m=x.docs.documento(x.f.a(x.f.profA),x.req,d.id());assertTrue(m.cuarentena());assertFalse(m.consultable());assertFalse(m.descargable());denied(423,()->x.docs.referencia(x.f.a(x.f.profA),x.req,d.id(),"CONTENIDO"));denied(404,()->x.docs.referencia(x.f.a(x.f.ti),x.req,d.id(),"CONTENIDO"));denied(403,()->f.q.ver(x.f.a(x.f.profA),h.id()));
  assertEquals(original,x.d.db.sql.queryForMap("SELECT * FROM institution_document WHERE id=?",d.id().toString()));assertEquals(policy,x.d.db.sql.queryForMap("SELECT * FROM requirement_document_policy WHERE document_id=?",d.id().toString()));assertArrayEquals(x.bytes().readAllBytes(),Files.readAllBytes(file));var json=x.d.mapper.valueToTree(h);for(String field:List.of("nombre","tipo","caso","requerimiento","comunicacion","relato","unidad","area"))assertFalse(json.has(field));
 }
 @Test void revisionDeOtraPersonaVerificaBytesYNoLevantaReservaInstitucional(){
  var x=f.x;var d=x.cargar();x.docs.proteger(x.f.a(x.f.headA),x.key(),x.req,d.id(),new DocumentosRequerimiento.Proteccion(0,"FIR","Reserva institucional independiente"));var calls=new AtomicInteger();var q=f.servicio(p->{calls.incrementAndGet();return true;},x.inspector);var hold=q.aislar(x.f.a(x.f.ti),x.key(),f.solicitud(d));UUID key=x.key();var r=new CuarentenaDocumental.Verificar(0,"Revisión técnica independiente completada");
  var released=q.verificar(x.f.a(f.peer),key,hold.id(),r);assertEquals("LIBERADO",released.estado());assertEquals(f.peer,released.liberadoPor());assertEquals(1,released.revision());q.verificar(x.f.a(f.peer),key,hold.id(),r);assertEquals(1,calls.get());assertEquals("FIR",x.docs.documento(x.f.a(x.f.profA),x.req,d.id()).proteccion());assertNotNull(x.docs.referencia(x.f.a(x.f.profA),x.req,d.id(),"CONTENIDO"));denied(404,()->x.docs.referencia(x.f.a(f.peer),x.req,d.id(),"DESCARGA"));
 }
 @Test void mismaPersonaEnCuentaAliasNoPuedeLiberar()throws Exception{var x=f.x;var h=aislar(x.cargar());String alias=f.ti("ti.alias","p-"+x.f.ti,f.peer);denied(403,()->f.q.verificar(x.f.a(x.f.ti),x.key(),h.id(),new CuarentenaDocumental.Verificar(0,"No revisa su propio aislamiento")));denied(403,()->f.q.verificar(x.f.a(alias),x.key(),h.id(),new CuarentenaDocumental.Verificar(0,"Alias no es independencia")));assertEquals("RETENIDO",f.q.ver(x.f.a(f.peer),h.id()).estado());}
 @Test void malwareFalloDeAntivirusYTipoIncompatibleConservanAislamiento(){var x=f.x;var d=x.cargar();var h=aislar(d);
  denied(422,()->f.servicio(p->false,x.inspector).verificar(x.f.a(f.peer),x.key(),h.id(),new CuarentenaDocumental.Verificar(0,"Malware aún detectado")));
  denied(503,()->f.servicio(p->{throw new IOException();},x.inspector).verificar(x.f.a(f.peer),x.key(),h.id(),new CuarentenaDocumental.Verificar(0,"Antivirus no disponible")));
  denied(503,()->f.servicio(p->true,(p,e)->new ProcesamientoDocumental.Examen("application/pdf","DESCARGA",null)).verificar(x.f.a(f.peer),x.key(),h.id(),new CuarentenaDocumental.Verificar(0,"Inspección no coincide")));
  assertEquals("RETENIDO",f.q.ver(x.f.a(f.peer),h.id()).estado());assertEquals(1,count("document_technical_command"));assertEquals(3,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM document_technical_history WHERE event_code='VERIFICACION_NO_COMPLETADA'",Long.class));
 }
 @Test void hashIncorrectoNoRevelaMetadatosNiCreaIncidente(){var x=f.x;var d=x.cargar();denied(404,()->f.q.aislar(x.f.a(x.f.ti),x.key(),new CuarentenaDocumental.Aislar(d.id(),"b".repeat(64),"INC-SINTETICO","Referencia sin hash íntegro")));assertEquals(0,count("document_technical_hold"));assertFalse(x.docs.documento(x.f.a(x.f.profA),x.req,d.id()).cuarentena());}
 @Test void concurrenciaDeAislamientoYReintentosNoCreaDosRetenciones()throws Exception{var x=f.x;var d=x.cargar();UUID key=x.key();var go=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<UUID> op=()->{go.await();return f.q.aislar(x.f.a(x.f.ti),key,f.solicitud(d)).id();};var a=pool.submit(op);var b=pool.submit(op);go.countDown();assertEquals(a.get(8,TimeUnit.SECONDS),b.get(8,TimeUnit.SECONDS));}assertEquals(1,count("document_technical_hold"));assertEquals(1,count("document_technical_command"));denied(409,()->aislar(d));}
 @Test void derivaPaginadaEsSoloTecnicaYExpiracionNoConservaAcceso(){var x=f.x;var h=aislar(x.cargar());var a=x.f.a(f.peer);var page=f.q.listar(a,"RETENIDO",0,1);assertEquals(1,page.total());assertEquals(h.id(),page.items().getFirst().id());assertTrue(page.items().getFirst().verificable());assertTrue(page.items().getFirst().historial().isEmpty());x.clock.avanzar(1801);denied(403,()->f.q.listar(a,"RETENIDO",0,1));assertEquals("RETENIDO",x.d.db.sql.queryForObject("SELECT state FROM document_technical_hold WHERE id=?",String.class,h.id().toString()));}
 @Test void cuarentenaDuranteDescargaDetieneSiguienteBloqueSinBorrarOriginal()throws Exception{var x=f.x;byte[] bytes=new byte[200000];Arrays.fill(bytes,(byte)'a');var d=x.docs.cargar(x.f.a(x.f.profA),x.key(),x.req,null,"largo.txt",new ByteArrayInputStream(bytes));var a=x.f.a(x.f.profA);var ref=x.docs.referencia(a,x.req,d.id(),"DESCARGA");var file=x.docs.verificarArchivo(ref);var request=new org.springframework.mock.web.MockHttpServletRequest("GET","/sintetico");var response=TransferenciaDocumento.responder(file,d.tamanio(),d.sha256(),d.nombre(),d.tipo(),false,request,m->{},()->x.docs.revalidar(a,x.req,d.id(),"DESCARGA"));var out=new ByteArrayOutputStream(){@Override public synchronized void write(byte[] b,int off,int len){super.write(b,off,len);aislar(d);}};denied(423,()->{try{response.getBody().writeTo(out);}catch(IOException e){throw new UncheckedIOException(e);}});assertEquals(65536,out.size());assertArrayEquals(bytes,Files.readAllBytes(file));}
 @Test void casoConservaMetadatosPeroNoBytesNiVistas(){var x=f.x;UUID c=x.abrir();var docs=new DocumentosGestion(x.d.db,x.files,new AutorizacionNucleo(x.f.core),p->true,x.inspector,x.clock);var d=docs.cargar(x.f.a(x.f.profA),x.key(),c,null,"caso.txt",x.bytes());f.q.aislar(x.f.a(x.f.ti),x.key(),new CuarentenaDocumental.Aislar(d.id(),d.sha256(),"INC-CASO","Bloqueo técnico sin modificar Caso"));assertTrue(docs.documento(x.f.a(x.f.profA),c,d.id()).cuarentena());assertFalse(docs.documento(x.f.a(x.f.profA),c,d.id()).consultable());denied(423,()->docs.referencia(x.f.a(x.f.profA),c,d.id()));assertEquals(1,docs.listar(x.f.a(x.f.profA),c).size());assertEquals("EN_GESTION",x.f.core.caso(x.f.a(x.f.profA),c).estado());}
 @Test void revocacionDuranteVerificacionImpideLiberarYConservaIntento(){var x=f.x;var h=aislar(x.cargar());var a=x.f.a(f.peer);var q=f.servicio(p->{x.clock.avanzar(1801);return true;},x.inspector);denied(403,()->q.verificar(a,x.key(),h.id(),new CuarentenaDocumental.Verificar(0,"No mantiene facultad al confirmar")));assertEquals("RETENIDO",x.d.db.sql.queryForObject("SELECT state FROM document_technical_hold WHERE id=?",String.class,h.id().toString()));assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM document_technical_history WHERE event_code='VERIFICACION_INICIADA'",Long.class));assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM document_technical_history WHERE event_code='VERIFICACION_NO_COMPLETADA'",Long.class));}
 @Test void falloDePersistenciaNoDejaLiberacionParcial(){var x=f.x;var h=aislar(x.cargar());x.d.ddl(sql->sql.execute("ALTER TABLE document_technical_hold ADD CONSTRAINT cuarentena_rollback CHECK(state='RETENIDO')"));try{var e=assertThrows(org.springframework.dao.DataAccessException.class,()->f.q.verificar(x.f.a(f.peer),x.key(),h.id(),new CuarentenaDocumental.Verificar(0,"No confirmar liberación parcial")));assertTrue(org.springframework.core.NestedExceptionUtils.getMostSpecificCause(e).getMessage().toLowerCase(Locale.ROOT).contains("cuarentena_rollback"));}finally{x.d.ddl(sql->sql.execute("ALTER TABLE document_technical_hold DROP "+(System.getProperty("siger.test.autoridad.mysql")==null?"CONSTRAINT":"CHECK")+" cuarentena_rollback"));}assertEquals("RETENIDO",f.q.ver(x.f.a(f.peer),h.id()).estado());assertEquals(1,count("document_technical_command"));assertEquals(0,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM document_technical_history WHERE event_code='DOCUMENTO_LIBERADO'",Long.class));}
 @Test void copiasConLaMismaHuellaNoEludenRetencionNiCreanUnNuevoDocumento(){var x=f.x;var a=x.cargar();var b=x.cargar();aislar(a);assertTrue(x.docs.documento(x.f.a(x.f.profA),x.req,b.id()).cuarentena());denied(423,()->x.docs.referencia(x.f.a(x.f.profA),x.req,b.id(),"DESCARGA"));denied(423,()->x.cargar());assertEquals(2,count("institution_document"));}
 @Test void retencionCreadaDuranteAntivirusImpideAltaDeCopiaEnCaso(){var x=f.x;var original=x.cargar();UUID cas=x.abrir();var docs=new DocumentosGestion(x.d.db,x.files,new AutorizacionNucleo(x.f.core),p->{aislar(original);return true;},x.inspector,x.clock);denied(423,()->docs.cargar(x.f.a(x.f.profA),x.key(),cas,null,"copia.txt",x.bytes()));assertEquals(1,count("institution_document"));assertEquals(0,count("management_document_link"));assertEquals(0,count("document_command"));}
 @Test void barreraTecnicaNoDependeDeAdaptadorDeAutorizacionNiCacheDelVisor()throws Exception{var x=f.x;UUID cas=x.abrir();var buffer=new ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",buffer);byte[] png=buffer.toByteArray();ProcesamientoDocumental.Inspector inspection=(p,e)->new ProcesamientoDocumental.Examen("image/png","PAGINAS",png);var real=new DocumentosGestion(x.d.db,x.files,new AutorizacionNucleo(x.f.core),p->true,inspection,x.clock);var d=real.cargar(x.f.a(x.f.profA),x.key(),cas,null,"cache.png",new ByteArrayInputStream(png));var ref=real.referencia(x.f.a(x.f.profA),cas,d.id());var render=org.mockito.Mockito.mock(ProcesamientoDocumental.Renderizador.class);var visor=new VisorDocumento(x.d.db,x.files,p->true,inspection,render,x.clock);assertEquals(1,visor.vista(ref).paginas());assertEquals(1,count("document_page"));var permissive=org.mockito.Mockito.mock(AutorizacionDocumental.class);var custom=new DocumentosGestion(x.d.db,x.files,permissive,p->true,inspection,x.clock);f.q.aislar(x.f.a(x.f.ti),x.key(),new CuarentenaDocumental.Aislar(d.id(),d.sha256(),"INC-ADAPTADOR","Ningún adaptador omite la barrera técnica"));denied(423,()->custom.referencia(x.f.a(x.f.profA),cas,d.id()));denied(423,()->custom.revalidar(x.f.a(x.f.profA),cas,d.id(),"DESCARGA"));denied(423,()->visor.vista(ref));denied(423,()->visor.pagina(ref,1));assertEquals(1,count("document_page"));org.mockito.Mockito.verifyNoInteractions(render);}
 @Test void reintentoConfirmadoDevuelveMetadatosSinTransmitirOriginalRetenido(){var x=f.x;UUID key=x.key();var doc=x.docs.cargar(x.f.a(x.f.profA),key,x.req,null,"confirmado.txt",x.bytes());UUID cas=x.abrir(),caseKey=x.key();var cases=new DocumentosGestion(x.d.db,x.files,new AutorizacionNucleo(x.f.core),p->true,x.inspector,x.clock);var caseDoc=cases.cargar(x.f.a(x.f.profA),caseKey,cas,null,"caso-confirmado.txt",x.bytes());aislar(doc);var repeated=x.docs.cargar(x.f.a(x.f.profA),key,x.req,null,"confirmado.txt",x.bytes());assertEquals(doc.id(),repeated.id());assertTrue(repeated.cuarentena());assertFalse(repeated.descargable());var repeatedCase=cases.cargar(x.f.a(x.f.profA),caseKey,cas,null,"caso-confirmado.txt",x.bytes());assertEquals(caseDoc.id(),repeatedCase.id());assertTrue(repeatedCase.cuarentena());assertFalse(repeatedCase.descargable());assertEquals(2,count("institution_document"));assertEquals(1,count("requirement_document_command"));assertEquals(1,count("document_command"));denied(423,()->x.docs.referencia(x.f.a(x.f.profA),x.req,doc.id(),"DESCARGA"));denied(423,()->cases.referencia(x.f.a(x.f.profA),cas,caseDoc.id(),"DESCARGA"));}

}
